                # Numeric sorts before non-numeric
                return -1
            elif is_digit2:
                # Non-numeric sorts after numeric
                return 1
            else:
                # Both non-numeric, compare ASCII
                if id1 != id2:
                    return -1 if id1 < id2 else 1

        # If all shared identifiers are equal, fewer sorts first
        if len(pre1) != len(pre2):
            return -1 if len(pre1) < len(pre2) else 1

        return 0

    def sort_key(v):
