        # Create a comparable key for pre-release
        if prerelease:
            # Versions with pre-release should sort before without
            pre_sort_key = (0, tuple((0 if x.isdigit() else 1, int(x) if x.isdigit() else x) for x in prerelease), len(prerelease))
